func TestKASAuthCommandHelp(t *testing.T) {
	// Fixtures were generated by the actual upstream add_kas_parser definitions,
	// not a stand-in CLI that assumes the auth verbs already exist.
	for _, tc := range []struct {
		name string
		want bool
	}{
		{"kirocrew-v0.10.0-kas-help.txt", false},
		{"kirocrew-d199f301-kas-help.txt", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			b, err := os.ReadFile(filepath.Join("testdata", tc.name))
			if err != nil {
				t.Fatal(err)
			}
			if got := kasAuthCommandsAvailable(string(b)); got != tc.want {
				t.Fatalf("available=%v, want %v", got, tc.want)
			}
		})
	}
	for _, tc := range []struct {
		help string
		want bool
	}{
		{"", false},
		{"login whoami logout are not supported", false},
		{"{install,status,remove} --description login whoami logout", false},
		{"{login,whoami}", false},
		{"{login,whoami} {logout}", false},
		{"{login,whoami,logout-extra}", false},
		{"usage: kirocrew kas [-h] { login,\n whoami, logout } ...", true},
		{"usage: kirocrew kas [-h] \x1b[32m{login,whoami,logout}\x1b[0m ...", true},
		{"usage: kirocrew kas [-h] {login,whoami,logout} ...\r\n", true},
		// The choice set must be the positional subcommands in usage.
		{"{login,whoami,logout}", false},
		{"usage: kirocrew kas [-h] {install,status,remove} ...\n\n  {login,whoami,logout}", false},
		{"usage: kirocrew kas [-h] [--operation {login,whoami,logout}] {install,status,remove} ...", false},
		{"usage: kirocrew kas [-h] [--operation\n    {login,whoami,logout}]\n    {install,status,remove} ...", false},
		{"usage: kirocrew kas [-h] --operation={login,whoami,logout} {install,status,remove} ...", false},
		// nargs and other multi-value option forms repeat or nest the choice set.
		{"usage: kirocrew kas [-h] [--operation {login,whoami,logout} {login,whoami,logout}] {install,status,remove} ...", false},
		{"usage: kirocrew kas [-h] --operation {login,whoami,logout}\n                    {login,whoami,logout}\n                    {install,status,remove} ...", false},
		{"usage: kirocrew kas [-h] [--operation {login,whoami,logout} {login,whoami,logout} {login,whoami,logout}] {install,status,remove} ...", false},
		{"usage: kirocrew kas [-h] [-o {login,whoami,logout} {login,whoami,logout}] {install,status,remove} ...", false},
		{"usage: kirocrew kas [-h] [--operation {login,whoami,logout} [{login,whoami,logout} ...]] {install,status,remove} ...", false},
		{"usage: kirocrew kas [-h] [--operation [{login,whoami,logout} ...]] {install,status,remove} ...", false},
		{"usage: kirocrew kas [-h] [--operation [{login,whoami,logout}]] {install,status,remove} ...", false},
		{"usage: kirocrew kas [-h] [--operation {login,whoami,logout} {login,whoami,logout}] {login,whoami,logout} ...", true},
		{"usage: kirocrew kas [-h] --operation {login,whoami,logout} {login,whoami,logout} {login,whoami,logout} ...", true},
		// A translated argparse heading is not the English usage block.
		{"utilisation : kirocrew kas [-h] {install,status,remove,login,whoami,logout} ...", false},
	} {
		if got := kasAuthCommandsAvailable(tc.help); got != tc.want {
			t.Errorf("available(%q)=%v, want %v", tc.help, got, tc.want)
		}
	}
}

func TestLegacyBackendDoesNotProbeKiroCrew(t *testing.T) {
	c := New(config.Config{KiroBin: "must-not-execute", KiroCrewBin: "must-not-execute"}, nil)
	if err := c.CheckCapabilities(context.Background()); err != nil {
		t.Fatal(err)
	}
}

func TestKASCapabilityProbeErrors(t *testing.T) {
	c := New(config.Config{Backend: config.BackendKAS,
		KiroCrewBin: filepath.Join(t.TempDir(), "absent-kirocrew"), CommandTimeout: time.Second}, nil)
	if err := c.CheckCapabilities(context.Background()); err == nil {
		t.Fatal("missing executable accepted")
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if err := c.CheckCapabilities(ctx); !errors.Is(err, context.Canceled) {
		t.Fatalf("cancellation lost: %v", err)
	}
	c.commandTimeout = -time.Second
	if err := c.CheckCapabilities(context.Background()); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("deadline lost: %v", err)
	}
}

func TestKASHelpProbeForcesCLocale(t *testing.T) {
	t.Setenv("LANGUAGE", "fr_FR")
	t.Setenv("LC_ALL", "fr_FR.UTF-8")
	c := kasClient(t, "localized-help", nil)
	if err := c.CheckCapabilities(context.Background()); err != nil {
		t.Fatal(err)
	}
}

func TestKASHelpProbeCancelReapsLingeringDescendant(t *testing.T) {
	pidPath := filepath.Join(t.TempDir(), "linger.pid")
	t.Setenv("KCLW_KAS_LINGER_PID", pidPath)
	c := kasClient(t, "linger-help", nil)
	c.commandTimeout = 150 * time.Millisecond
	t.Cleanup(func() { killLingerPID(pidPath) })

	started := time.Now()
	err := c.CheckCapabilities(context.Background())
	elapsed := time.Since(started)
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("elapsed=%s err=%v", elapsed, err)
	}
	// The descendant holds the pipe for 20s. Cancel must close the read end
	// and reap the direct child instead of waiting out that hold.
	if elapsed > time.Second {
		t.Fatalf("probe returned after %s; cancel did not unblock the read", elapsed)
	}
	pid, readErr := os.ReadFile(pidPath)
	if readErr != nil {
		t.Fatalf("descendant was not started: %v", readErr)
	}
	n, convErr := strconv.Atoi(strings.TrimSpace(string(pid)))
	if convErr != nil || n <= 0 {
		t.Fatalf("descendant pid %q: %v", pid, convErr)
	}
	if runtime.GOOS != "windows" {
		if err := syscall.Kill(n, 0); err != nil {
			t.Fatalf("descendant pid %d was not alive after the probe: %v", n, err)
		}
	}
}

func killLingerPID(path string) {
	pid, err := os.ReadFile(path)
	if err != nil {
		return
	}
	n, err := strconv.Atoi(strings.TrimSpace(string(pid)))
	if err != nil || n <= 0 {
		return
	}
	proc, err := os.FindProcess(n)
	if err != nil {
		return
	}
	_ = proc.Kill()
}

func TestKASChoiceScanStaysLinear(t *testing.T) {
	var b strings.Builder
	b.Grow(256*1024 + 64)
	b.WriteString("usage: kirocrew kas [-h] ")
	for b.Len() < 250*1024 {
		b.WriteString("{x}")
	}
	b.WriteString("{login,whoami,logout} ...\n")
	started := time.Now()
	if !kasAuthCommandsAvailable(b.String()) {
		t.Fatal("subparser after many choice sets was missed")
	}
	if elapsed := time.Since(started); elapsed > time.Second {
		t.Fatalf("choice scan took %s", elapsed)
	}

	// An unclosed option bracket still hides a later set that looks like a subparser.
	var hidden strings.Builder
	hidden.WriteString("usage: kirocrew kas [-h] [--operation ")
	for hidden.Len() < 64*1024 {
		hidden.WriteString("{login,whoami,logout} ")
	}
	hidden.WriteString("{login,whoami,logout} ...]\n")
	if kasAuthCommandsAvailable(hidden.String()) {
		t.Fatal("choice set inside an unclosed option bracket was accepted")
	}
}

func TestKASHelpProbeRejectsOversizedOutput(t *testing.T) {
	c := kasClient(t, "huge-help", nil)
	err := c.CheckCapabilities(context.Background())
	if !errors.Is(err, errKASHelpTooLarge) {
		t.Fatalf("oversized help: %v", err)
	}
}
